<?php require_once "../db.php";require_role("Admin");$id=(int)($_GET['id']??0);$st=$conn->prepare("SELECT id,name,email,subject FROM teacher WHERE id=?");$st->bind_param("i",$id);$st->execute();$teacher=$st->get_result()->fetch_assoc();if(!$teacher){http_response_code(404);die('Teacher not found. <a href="teachers.php">Back to teachers</a>');}
$q=$conn->prepare("SELECT id,title,subject,duration,total_questions,created_at FROM quiz WHERE created_by=? ORDER BY created_at DESC");$q->bind_param("i",$id);$q->execute();$quizzes=$q->get_result();$m=$conn->prepare("SELECT id,title,subject,created_at FROM practice_material WHERE created_by=? ORDER BY created_at DESC");$m->bind_param("i",$id);$m->execute();$materials=$m->get_result();$h=$conn->prepare("SELECT h.id,h.created_at,h.score,h.total_questions,s.name student_name,q.title quiz_title FROM quiz_history h JOIN quiz q ON q.id=h.quiz_id JOIN student s ON s.id=h.student_id WHERE q.created_by=? ORDER BY h.created_at DESC");$h->bind_param("i",$id);$h->execute();$attempts=$h->get_result();?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher Activity</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/admin_sidebar.php";?></div><main class="col-lg-10"><div class="py-4 px-lg-3"><a href="teachers.php" class="btn btn-sm btn-outline-secondary mb-3">← Teachers</a><h2 class="fw-bold"><?=e($teacher['name'])?> — Activity</h2><p class="text-muted"><?=e($teacher['email'])?> · Subject: <?=e($teacher['subject'])?></p><div class="card panel-card mb-4"><div class="card-body"><h5>Quizzes Created</h5><div class="table-responsive"><table class="table"><thead><tr><th>Quiz</th><th>Subject</th><th>Duration</th><th>Questions</th><th>Created</th><th></th></tr></thead><tbody><?php if(!$quizzes->num_rows):?><tr><td colspan="6">No quizzes created.</td></tr><?php endif;?><?php while($x=$quizzes->fetch_assoc()):?><tr><td><?=e($x['title'])?></td><td><?=e($x['subject'])?></td><td><?=$x['duration']?> min</td><td><?=$x['total_questions']?></td><td><?=e($x['created_at'])?></td><td><a href="quiz_history.php?quiz_id=<?=$x['id']?>">Attempts</a></td></tr><?php endwhile;?></tbody></table></div></div></div><div class="card panel-card mb-4"><div class="card-body"><h5>Practice Materials Created</h5><div class="table-responsive"><table class="table"><thead><tr><th>Title</th><th>Subject</th><th>Created</th></tr></thead><tbody><?php if(!$materials->num_rows):?><tr><td colspan="3">No materials created.</td></tr><?php endif;?><?php while($x=$materials->fetch_assoc()):?><tr><td><?=e($x['title'])?></td><td><?=e($x['subject'])?></td><td><?=e($x['created_at'])?></td></tr><?php endwhile;?></tbody></table></div></div></div><div class="card panel-card"><div class="card-body"><h5>Student Attempts on This Teacher's Quizzes</h5><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Quiz</th><th>Score</th><th>Date</th></tr></thead><tbody><?php if(!$attempts->num_rows):?><tr><td colspan="4">No attempts yet.</td></tr><?php endif;?><?php while($x=$attempts->fetch_assoc()):?><tr><td><?=e($x['student_name'])?></td><td><?=e($x['quiz_title'])?></td><td><?=$x['score']?>/<?=$x['total_questions']?></td><td><a href="quiz_attempt.php?id=<?=$x['id']?>"><?=e($x['created_at'])?></a></td></tr><?php endwhile;?></tbody></table></div></div></div></div></main></div></div><script src="../assets/card-links.js"></script></body></html>
